// src/db/index.ts
import { drizzle } from 'drizzle-orm/node-postgres';
import { Pool } from 'pg';
import * as schema from './schema';

const pool = new Pool({ connectionString: process.env.DATABASE_URL, max: 10 });

export const db = drizzle({ client: pool, schema, casing: 'snake_case' });

// Shorthand: drizzle(process.env.DATABASE_URL!) creates the pool for you

// src/db/schema.ts
import { pgTable, integer, text, varchar, timestamp, boolean, index } from 'drizzle-orm/pg-core';

export const users = pgTable('users', {
  id: integer().primaryKey().generatedAlwaysAsIdentity(),
  email: varchar({ length: 255 }).notNull().unique(),
  name: text(),
  createdAt: timestamp({ withTimezone: true }).defaultNow().notNull()
});

export const posts = pgTable(
  'posts',
  {
    id: integer().primaryKey().generatedAlwaysAsIdentity(),
    title: text().notNull(),
    published: boolean().default(false).notNull(),
    authorId: integer().notNull().references(() => users.id, { onDelete: 'cascade' })
  },
  (t) => [index('posts_author_idx').on(t.authorId)]
);

import { eq } from 'drizzle-orm';
import { db } from './db';
import { users } from './db/schema';

const [created] = await db.insert(users)
  .values({ email: 'asha@example.com', name: 'Asha' })
  .returning();

const found = await db.select().from(users).where(eq(users.id, created.id));
// found: { id: number; email: string; name: string | null; createdAt: Date }[]

import { pgTable, uuid, text, timestamp, jsonb } from 'drizzle-orm/pg-core';
import { sql } from 'drizzle-orm';

type Settings = { theme: 'light' | 'dark'; emails: boolean };

export const accounts = pgTable('accounts', {
  id: uuid().primaryKey().defaultRandom(),
  slug: text().notNull().unique(),
  settings: jsonb().$type<Settings>().default({ theme: 'light', emails: true }).notNull(),
  createdAt: timestamp({ withTimezone: true }).defaultNow().notNull(),
  updatedAt: timestamp({ withTimezone: true }).defaultNow().notNull().$onUpdate(() => new Date())
});

import { pgTable, integer, primaryKey, timestamp } from 'drizzle-orm/pg-core';

export const usersToGroups = pgTable(
  'users_to_groups',
  {
    userId: integer().notNull().references(() => users.id, { onDelete: 'cascade' }),
    groupId: integer().notNull().references(() => groups.id, { onDelete: 'cascade' }),
    joinedAt: timestamp().defaultNow().notNull()
  },
  (t) => [primaryKey({ columns: [t.userId, t.groupId] })]
);

import { pgTable, integer, text, numeric, timestamp, index, uniqueIndex, check } from 'drizzle-orm/pg-core';
import { sql } from 'drizzle-orm';

export const products = pgTable(
  'products',
  {
    id: integer().primaryKey().generatedAlwaysAsIdentity(),
    tenantId: integer().notNull(),
    sku: text().notNull(),
    price: numeric({ precision: 12, scale: 2 }).notNull(),
    deletedAt: timestamp()
  },
  (t) => [
    uniqueIndex('products_tenant_sku_uq').on(t.tenantId, t.sku).where(sql`${t.deletedAt} is null`),
    index('products_tenant_idx').on(t.tenantId),
    check('products_price_check', sql`${t.price} >= 0`)
  ]
);

import { pgEnum, pgTable, integer, text } from 'drizzle-orm/pg-core';

export const roleEnum = pgEnum('role', ['user', 'admin']);

export const members = pgTable('members', {
  id: integer().primaryKey().generatedAlwaysAsIdentity(),
  role: roleEnum().default('user').notNull(),
  plan: text({ enum: ['free', 'pro', 'team'] }).default('free').notNull() // TS-only enum
});

import { and, desc, eq, gte, ilike, or } from 'drizzle-orm';

const recent = await db
  .select({ id: posts.id, title: posts.title, createdAt: posts.createdAt })
  .from(posts)
  .where(
    and(
      eq(posts.published, true),
      gte(posts.createdAt, new Date('2026-01-01')),
      or(ilike(posts.title, '%drizzle%'), ilike(posts.title, '%sql%'))
    )
  )
  .orderBy(desc(posts.createdAt), desc(posts.id))
  .limit(20);

import { sql } from 'drizzle-orm';

const [user] = await db
  .insert(users)
  .values({ email: 'asha@example.com', name: 'Asha' })
  .onConflictDoUpdate({
    target: users.email,
    set: { name: sql`excluded.name` }
  })
  .returning({ id: users.id, email: users.email });

await db.insert(tags).values([{ name: 'sql' }, { name: 'orm' }]).onConflictDoNothing();

const updated = await db
  .update(products)
  .set({ stock: sql`${products.stock} - ${qty}` })
  .where(and(eq(products.id, id), gte(products.stock, qty)))
  .returning({ stock: products.stock });

if (updated.length === 0) throw new Error('Out of stock');

await db.delete(sessions).where(lt(sessions.expiresAt, new Date()));

// drizzle.config.ts
import 'dotenv/config';
import { defineConfig } from 'drizzle-kit';

export default defineConfig({
  dialect: 'postgresql',
  schema: './src/db/schema.ts',
  out: './drizzle',
  casing: 'snake_case',
  dbCredentials: { url: process.env.DATABASE_URL! },
  strict: true,
  verbose: true
});

// scripts/migrate.ts (run once per deploy, not on every app instance start)
import { drizzle } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';

const db = drizzle(process.env.DATABASE_URL!);
await migrate(db, { migrationsFolder: './drizzle' });
console.log('migrations applied');
process.exit(0);

const rows = await db
  .select({
    userId: users.id,
    email: users.email,
    postTitle: posts.title // string | null because of leftJoin
  })
  .from(users)
  .leftJoin(posts, eq(posts.authorId, users.id))
  .where(eq(users.id, 1));

import { relations } from 'drizzle-orm';

export const usersRelations = relations(users, ({ many }) => ({
  posts: many(posts)
}));

export const postsRelations = relations(posts, ({ one, many }) => ({
  author: one(users, { fields: [posts.authorId], references: [users.id] }),
  comments: many(comments)
}));

const result = await db.query.users.findMany({
  columns: { id: true, name: true },
  where: (u, { eq }) => eq(u.active, true),
  with: {
    posts: {
      columns: { id: true, title: true },
      where: (p, { eq }) => eq(p.published, true),
      orderBy: (p, { desc }) => [desc(p.createdAt)],
      limit: 3,
      with: { comments: { columns: { id: true } } }
    }
  },
  limit: 20
});
// { id: number; name: string | null; posts: { id: number; title: string; comments: { id: number }[] }[] }[]

export type User = typeof users.$inferSelect;
// { id: number; email: string; name: string | null; createdAt: Date }

export type NewUser = typeof users.$inferInsert;
// { id?: number; email: string; name?: string | null; createdAt?: Date }

export async function createUser(input: NewUser): Promise<User> {
  const [row] = await db.insert(users).values(input).returning();
  return row;
}

import { createInsertSchema, createSelectSchema } from 'drizzle-zod';
import { z } from 'zod';

export const insertUserSchema = createInsertSchema(users, {
  email: (s) => s.email().max(255),
  name: (s) => s.min(1).max(80)
}).omit({ id: true, createdAt: true });

export const selectUserSchema = createSelectSchema(users);

// Route handler
const body = insertUserSchema.parse(await req.json());
const [user] = await db.insert(users).values(body).returning();

