const transfer = await db.transaction(async (tx) => {
  const [from] = await tx
    .update(accounts)
    .set({ balance: sql`${accounts.balance} - ${amount}` })
    .where(and(eq(accounts.id, fromId), gte(accounts.balance, amount)))
    .returning();
  if (!from) tx.rollback(); // insufficient funds: throws and rolls back

  await tx
    .update(accounts)
    .set({ balance: sql`${accounts.balance} + ${amount}` })
    .where(eq(accounts.id, toId));

  const [row] = await tx.insert(transfers).values({ fromId, toId, amount }).returning();
  return row;
}, { isolationLevel: 'read committed' });

// Safe: term is a bound parameter, columns are quoted identifiers
const rows = await db
  .select({
    id: posts.id,
    rank: sql<number>`ts_rank(${posts.searchVector}, websearch_to_tsquery('english', ${term}))`.as('rank')
  })
  .from(posts)
  .where(sql`${posts.searchVector} @@ websearch_to_tsquery('english', ${term})`)
  .orderBy(sql`rank desc`)
  .limit(20);

// Locking for a job queue
const [job] = await db.select().from(jobs)
  .where(eq(jobs.status, 'queued'))
  .orderBy(jobs.runAt)
  .limit(1)
  .for('update', { skipLocked: true });

const getUserById = db
  .select()
  .from(users)
  .where(eq(users.id, sql.placeholder('id')))
  .prepare('get_user_by_id');

const [user] = await getUserById.execute({ id: 42 });

// Relational queries can be prepared too
const userWithPosts = db.query.users.findFirst({
  where: (u, { eq }) => eq(u.id, sql.placeholder('id')),
  with: { posts: true }
}).prepare('user_with_posts');

import type { PgSelect } from 'drizzle-orm/pg-core';

function withPagination<T extends PgSelect>(qb: T, page = 1, size = 20) {
  return qb.limit(size).offset((page - 1) * size);
}

const query = db.select().from(users).where(eq(users.active, true)).$dynamic();
const page2 = await withPagination(query, 2);

